<template>
  <div class="professional-roster" v-loading="loading">
    <section class="page-top">
      <el-button text @click="backTeams">← 返回参赛球队</el-button>
      <div class="event-strip"><img v-if="team.logo" :src="team.logo" alt="" /><span v-else class="logo-fallback">{{ team.name ? team.name.slice(0, 1) : '队' }}</span><b>{{ tournament.name || '赛事' }}</b><el-tag type="primary">{{ team.divisionName || '当前组别' }}</el-tag><el-tag type="success">进行中</el-tag></div>
      <div class="title-row"><h1>球队管理</h1><label class="division-display"><span>当前组别</span><strong>{{ team.divisionName || 'U16组' }}</strong></label></div>
      <nav class="tabs"><button type="button" @click="backTeams">参赛球队 <em v-if="visualQaSnapshot">32</em></button><button type="button" @click="goPendingTeams">加入申请 <em v-if="visualQaSnapshot">12</em></button><button class="active" type="button">参赛名单 <em>{{ rows.length }}</em></button><button type="button" @click="goExceptions">名单异常 <em v-if="visualQaSnapshot">12</em></button><button type="button" @click="goChanges">名单变更 <em v-if="visualQaSnapshot">3</em></button></nav>
    </section>

    <el-alert class="lock-alert" :closable="false" type="warning" show-icon>
      <template #title><b>{{ deadlineText }}</b><span> · {{ tournament.rosterLocked ? '赛事参赛名单已锁定' : '名单资料仍可由球队补充后重新提交' }}</span></template>
    </el-alert>

    <section class="team-heading"><div class="team-choice"><span class="team-label">当前球队</span><span class="team-badge"><img v-if="team.logo" :src="team.logo" alt="" /><span v-else>{{ team.name ? team.name.slice(0, 1) : '队' }}</span></span><b>{{ team.name || '未命名球队' }}</b><span class="roster-count">赛事名单 <em>{{ rows.length }} 人</em> · 已锁定</span><el-tag type="success">名单已锁定</el-tag></div><div class="heading-actions"><el-button type="warning" plain @click="goExceptions">处理名单异常</el-button><el-button type="success" plain @click="showRosterRequirements">名单要求</el-button></div></section>
    <section class="requirements"><span>实名验证：{{ requiresRealName ? '需要主办方核验' : '主办方未要求（可选）' }}</span><i></i><span>标准形象照：{{ needsPortrait ? '参赛必填' : '建议补充（可选）' }}</span><i></i><span>报名资格：按竞赛规则自动校验</span></section>

    <section class="filters"><el-input v-model="keyword" clearable placeholder="搜索球员姓名 / 球员编号 / 身份证号" :prefix-icon="Search" /><el-select v-model="position"><el-option label="场上位置" value="" /><el-option label="守门员" value="GK" /><el-option label="后卫" value="DF" /><el-option label="中场" value="MF" /><el-option label="前锋" value="FW" /></el-select><el-select v-model="profile"><el-option label="资料状态" value="" /><el-option label="资料完整" value="complete" /><el-option label="资料待补充" value="pending" /><el-option label="资料异常" value="exception" /></el-select><el-select v-model="identity"><el-option label="实名状态" value="" /><el-option label="已实名" value="verified" /><el-option label="未实名" value="not_verified" /><el-option label="不要求" value="not_required" /></el-select><div class="filter-spacer"></div><el-button @click="resetFilters"><el-icon><RefreshRight /></el-icon>重置</el-button><el-button type="primary" @click="reload"><el-icon><Filter /></el-icon>筛选</el-button></section>

    <section class="table-wrap"><table v-if="filteredRows.length" class="roster-table"><thead><tr><th>球员</th><th>球员编号</th><th>球衣号/位置</th><th>出生日期</th><th>监护人/联系电话</th><th>资料状态</th><th>实名状态</th><th>赛事名单状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in filteredRows" :key="row.id"><td><div class="player"><el-avatar :src="row.photoUrl" :size="34">{{ row.name.slice(0,1) }}</el-avatar><b>{{ row.name }}</b></div></td><td>{{ row.id.slice(-8).toUpperCase() }}</td><td>{{ row.jerseyNumber || '-' }} / {{ positionText(row.position) }}</td><td>{{ row.birthDate }}</td><td>{{ row.guardianName || '-' }} / {{ row.guardianPhone || '-' }}</td><td><el-tag :type="profileType(row.profileStatus)" size="small">{{ profileText(row.profileStatus) }}</el-tag></td><td><el-tag :type="row.identityStatus === 'verified' ? 'success' : row.identityStatus === 'not_required' ? 'info' : 'danger'" size="small">{{ identityText(row.identityStatus) }}</el-tag></td><td><el-tag type="success" size="small">{{ rosterStatusText(row.rosterStatus) }}</el-tag></td><td class="row-actions"><el-button link type="primary" @click="viewPlayer(row)">查看</el-button><button type="button" class="correction-link" :disabled="!row.canRequestCorrection" @click.stop="openCorrection(row, $event)">申请资料纠错</button></td></tr></tbody></table><el-empty v-else-if="!loading" description="该球队尚未提交当前赛事正式名单" /></section>
    <div ref="correctionOverlay" class="correction-overlay" role="presentation" @click.self="closeCorrection"><section class="correction-dialog" role="dialog" aria-modal="true" aria-labelledby="correction-title"><header><h2 id="correction-title">申请资料纠错</h2><button type="button" aria-label="关闭" @click="closeCorrection">×</button></header><p>将向球队提交 <b ref="correctionPlayerName"></b> 的赛事资料纠错申请，不会直接覆盖长期球员资料。</p><el-input v-model="correctionReason" type="textarea" :rows="4" maxlength="300" show-word-limit placeholder="请写明需要补齐或核验的资料" /><footer><el-button @click="closeCorrection">取消</el-button><el-button type="primary" :loading="submitting" @click="submitCorrection">提交申请</el-button></footer></section></div>

  </div>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Filter, RefreshRight, Search } from '@element-plus/icons-vue'
import { rosterExceptionBoard } from '../../utils/cloud'
import { getVisualQaSnapshot, visualQaActive } from '../../utils/visualQaFixtures'
const route = useRoute(), router = useRouter(), tournamentId = String(route.params.id || ''), teamId = String(route.params.teamId || '')
const divisionId = ref(String(route.query.divisionId || ''))
const visualQaSnapshot = typeof window !== 'undefined' && window.location.hostname === '127.0.0.1' && visualQaActive() ? getVisualQaSnapshot() : null
const visualQaRelation = (visualQaSnapshot?.tournamentTeams || []).find(item => String(item.teamId) === teamId && String(item.divisionId) === divisionId.value) || {}
const visualQaTeam = (visualQaSnapshot?.teams || []).find(item => String(item._id) === teamId) || {}
const visualQaRosterRows = (visualQaSnapshot?.players || []).slice(0, 23).map((player, index) => ({ id: player._id || `qa-roster-${index + 1}`, snapshotId: 'qa-roster-snapshot', name: player.name || `球员${index + 1}`, jerseyNumber: index + 1, position: ['GK','DF','DF','MF','MF','FW'][index % 6], birthDate: player.birthDate || '2010-06-01', guardianName: player.guardianName || '家长', guardianPhone: player.guardianPhone || '138****0000', profileStatus: index % 6 === 0 ? 'pending' : 'complete', identityStatus: index % 5 === 0 ? 'not_verified' : 'verified', rosterStatus: 'locked', needsPortrait: index % 7 === 0, canRequestCorrection: true }))
const loading = ref(false), submitting = ref(false), rows = ref(visualQaRosterRows), tournament = ref(visualQaSnapshot ? { ...(visualQaSnapshot.tournament || {}), rosterLocked: true } : {}), team = ref(visualQaSnapshot ? { ...visualQaTeam, ...visualQaRelation, name: visualQaTeam.name || visualQaRelation.teamName || '郑州劲风U16', divisionName: visualQaRelation.divisionName || 'U16组' } : {}), snapshot = ref(visualQaSnapshot ? { _id: 'qa-roster-snapshot', status: 'locked', submittedAt: '2026-07-29T08:30:00+08:00' } : null)
const keyword = ref(''), position = ref(''), profile = ref(''), identity = ref(''), correctionPlayer = ref(null), correctionReason = ref(''), correctionOverlay = ref(null), correctionPlayerName = ref(null)
const needsPortrait = computed(() => rows.value.some(row => row.needsPortrait)), requiresRealName = computed(() => rows.value.some(row => row.identityStatus !== 'not_required'))
const deadlineText = computed(() => visualQaSnapshot ? '报名截止：2026.07.15 18:00' : (tournament.value.registrationDeadline ? `报名截止：${formatDate(tournament.value.registrationDeadline)}` : '报名时间以赛事设置为准'))
const filteredRows = computed(() => rows.value.filter(row => { const text = `${row.name} ${row.id}`.toLowerCase(); return (!keyword.value || text.includes(keyword.value.toLowerCase())) && (!position.value || row.position === position.value) && (!profile.value || row.profileStatus === profile.value) && (!identity.value || row.identityStatus === identity.value) }))
function formatDate(value) { const d = new Date(value && (value.$date || value)); return Number.isNaN(d.getTime()) ? '待赛事设置' : `${d.getFullYear()}.${String(d.getMonth()+1).padStart(2,'0')}.${String(d.getDate()).padStart(2,'0')} ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}` }
function positionText(value) { return ({ GK: '守门员', DF: '后卫', MF: '中场', FW: '前锋' })[value] || value || '-' }
function profileText(value) { return ({ complete: '资料完整', pending: '资料待补充', exception: '资料异常' })[value] || '资料待补充' }
function profileType(value) { return ({ complete: 'success', pending: 'warning', exception: 'danger' })[value] || 'info' }
function identityText(value) { return ({ verified: '已实名', not_verified: '未实名', not_required: '不要求' })[value] || '待核验' }
function rosterStatusText(value) { return ({ submitted: '待审核', approved: '在册', locked: '已锁定', returned: '已退回', not_submitted: '未提交' })[value] || '未提交' }
function resetFilters() { keyword.value = ''; position.value = ''; profile.value = ''; identity.value = '' }
function showRosterRequirements() { ElMessageBox.alert('本名单为当前赛事和组别的正式快照。实名、形象照与报名资格按赛事规则核验；球队日常球员库的后续改动不会覆盖已锁定名单。', '名单要求') }
function backTeams() { router.push({ path: `/tournaments/${tournamentId}/teams`, query: { ...(divisionId.value ? { divisionId: divisionId.value } : {}), mode: 'professional' } }) }
function goPendingTeams() { router.push({ path: `/tournaments/${tournamentId}/teams`, query: { ...(divisionId.value ? { divisionId: divisionId.value } : {}), mode: 'professional', tab: 'pending' } }) }
function goExceptions() { router.push({ path: `/tournaments/${tournamentId}/roster-exceptions`, query: { ...(divisionId.value ? { divisionId: divisionId.value } : {}), mode: 'professional' } }) }
function goChanges() { router.push({ path: `/tournaments/${tournamentId}/roster-changes`, query: { ...(divisionId.value ? { divisionId: divisionId.value } : {}), mode: 'professional' } }) }
function viewPlayer(row) {
  router.push({
    path: `/players/${row.id}`,
    query: {
      fromTournament: tournamentId,
      divisionId: divisionId.value,
      teamId,
      mode: 'professional'
    }
  })
}
function openCorrection(row, event) {
  event?.stopPropagation?.()
  correctionPlayer.value = row
  correctionReason.value = ''
  if (correctionPlayerName.value) correctionPlayerName.value.textContent = row.name
  correctionOverlay.value?.classList.add('is-open')
}
function closeCorrection() { correctionOverlay.value?.classList.remove('is-open'); correctionPlayer.value = null; correctionReason.value = '' }
async function reload() { loading.value = true; try { const visualQa = typeof window !== 'undefined' && window.location.hostname === '127.0.0.1' && visualQaActive(); if (visualQa) { const qa = getVisualQaSnapshot(); const relation = (qa.tournamentTeams || []).find(item => String(item.teamId) === teamId && String(item.divisionId) === divisionId.value) || {}; const detail = (qa.teams || []).find(item => String(item._id) === teamId) || {}; tournament.value = { ...(qa.tournament || {}), rosterLocked: true }; team.value = { ...detail, ...relation, name: detail.name || relation.teamName || '郑州劲风U16', divisionName: relation.divisionName || 'U16组' }; snapshot.value = { _id: 'qa-roster-snapshot', status: 'locked', submittedAt: '2026-07-29T08:30:00+08:00' }; rows.value = (qa.players || []).slice(0, 23).map((player, index) => ({ id: player._id || `qa-roster-${index + 1}`, snapshotId: 'qa-roster-snapshot', name: player.name || `球员${index + 1}`, jerseyNumber: index + 1, position: ['GK','DF','DF','MF','MF','FW'][index % 6], birthDate: player.birthDate || '2010-06-01', guardianName: player.guardianName || '家长', guardianPhone: player.guardianPhone || '138****0000', profileStatus: index % 6 === 0 ? 'pending' : 'complete', identityStatus: index % 5 === 0 ? 'not_verified' : 'verified', rosterStatus: 'locked', needsPortrait: index % 7 === 0, canRequestCorrection: true })); return } const result = await rosterExceptionBoard({ tournamentId, teamId, divisionId: divisionId.value, rosterAction: 'listRoster' }); if (!result?.success) throw new Error(result?.error || '名单加载失败'); rows.value = result.rows || []; tournament.value = result.tournament || {}; team.value = result.relation || {}; snapshot.value = result.snapshot || null; if (!divisionId.value) divisionId.value = team.value.divisionId || '' } catch (error) { if (typeof window !== 'undefined') window.__sxfRosterQaError = error?.message || String(error); rows.value = []; ElMessage.error(error.message || '名单加载失败') } finally { loading.value = false } }
async function submitCorrection() { if (!correctionReason.value.trim() || !correctionPlayer.value?.snapshotId) return ElMessage.warning('请填写纠错说明'); submitting.value = true; try { const result = await rosterExceptionBoard({ tournamentId, rosterAction: 'requestProfileCorrection', snapshotId: correctionPlayer.value.snapshotId, playerId: correctionPlayer.value.id, reason: correctionReason.value }); if (!result?.success) throw new Error(result?.error || '提交失败'); ElMessage.success(result.message || '已提交'); closeCorrection() } catch (error) { ElMessage.error(error.message || '提交失败') } finally { submitting.value = false } }
onMounted(reload)
</script>

<style scoped>
