52;font-size:13px}.requirements i{width:1px;height:17px;background:#e5e7eb}.filters{display:flex;gap:12px;margin-bottom:9px}.filters .el-input{width:330px}.filters .el-select{width:158px}.filter-spacer{flex:1}.table-wrap{border:1px solid #e8ece9;border-radius:8px;overflow:auto}.roster-table{width:100%;min-width:1120px;border-collapse:collapse;font-size:13px;color:#344052}.roster-table th{height:38px;padding:0 12px;text-align:left;font-weight:600;color:#526071;background:#f8faf8;white-space:nowrap}.roster-table td{height:43px;padding:0 12px;border-top:1px solid #edf0ed;white-space:nowrap}.roster-table tr:hover td{background:#f8fcf9}.player{display:flex;align-items:center;gap:8px}.player :deep(.el-avatar){background:#edf3f8;color:#536579}.row-actions{min-width:154px}.correction-link{padding:0 4px;border:0;background:transparent;color:#409eff;font:inherit;cursor:pointer}.correction-link:disabled{color:#a8abb2;cursor:not-allowed}.correction-overlay{position:fixed;inset:0;z-index:2100;display:none;place-items:center;background:rgba(0,0,0,.46)}.correction-overlay.is-open{display:grid}.correction-dialog{width:min(500px,calc(100vw - 48px));padding:20px;border-radius:8px;background:#fff;box-shadow:0 18px 60px rgba(0,0,0,.22)}.correction-dialog header,.correction-dialog footer{display:flex;align-items:center;justify-content:space-between}.correction-dialog h2{margin:0;font-size:18px}.correction-dialog header button{border:0;background:transparent;color:#909399;font-size:24px;cursor:pointer}.correction-dialog p{margin:18px 0;color:#526071;line-height:1.65}.correction-dialog footer{justify-content:flex-end;gap:10px;margin-top:18px}@media(max-width:1000px){.tabs{gap:18px}.filters{flex-wrap:wrap}.filters .el-input{width:100%}.filter-spacer{display:none}.requirements{flex-wrap:wrap;gap:12px}}
